INSERT IGNORE INTO contents (content_id, title, category, subcategory, release_year, status, description, cast_names, thumbnail_url, is_popular, country, ott_platform, tags, created_at)
VALUES
('C_DRAMA_001', '선재 업고 튀어', '드라마', 'K-Drama', 2024, '공개', '최애 아티스트 류선재의 죽음으로 절망한 팬 임솔이 2008년으로 돌아가 그를 살리려는 타임슬립 로맨스 드라마.', '변우석, 김혜윤, 송건희, 이승협', 'https://upload.wikimedia.org/wikipedia/en/6/67/Lovely_Runner.png', TRUE, 'Korea', 'tvN / TVING', '수원,행궁동,화홍문,카페,타임슬립,로맨스,아이돌', CURRENT_TIMESTAMP),
('C_DRAMA_002', '눈물의 여왕', '드라마', 'K-Drama', 2024, '공개', '재벌 3세 홍해인과 용두리 출신 백현우 부부가 위기 속에서 다시 사랑을 시작하는 로맨틱 코미디 드라마.', '김수현, 김지원, 박성훈, 곽동연', 'https://i.namu.wiki/i/x0WGLEUNGjH3bKH-0U0luInQEnE9QWJFSezNrO7pxZOMfuLLFsQIDxVi1bJIlNIq0MWHoKhESNLy7S1lL6J-Ag.webp', TRUE, 'Korea', 'tvN / TVING / Netflix', '서울,수원,문경,독일,로맨스,재벌,부부', CURRENT_TIMESTAMP),
('C_DRAMA_003', '폭싹 속았수다', '드라마', 'K-Drama', 2025, '공개', '제주 바닷가 마을에서 자라온 애순과 관식의 인생을 사계절처럼 펼쳐 보이는 휴먼 로맨스 드라마.', '아이유, 박보검, 문소리, 박해준', 'https://i.namu.wiki/i/rXuE35p4JOShHlg__FAsMz0ZAVLSnBcAJlB33dMk8lPETYbiqj6qsaZWs2xuY5veM7NktKWD6KDknQbz6Ht7EQ.webp', TRUE, 'Korea', 'Netflix', '제주,사계절,해녀,사투리,가족,로맨스,지역문화', CURRENT_TIMESTAMP),
('C_DRAMA_004', '오징어 게임', '드라마', 'K-Drama', 2021, '공개', '빚에 쫓기는 사람들이 거액의 상금을 놓고 치명적인 서바이벌 게임에 참가하는 스릴러 드라마.', '이정재, 박해수, 정호연, 위하준, 오영수', 'https://upload.wikimedia.org/wikipedia/en/7/7b/Squid_Game_season_1_poster.png', TRUE, 'Korea', 'Netflix', '서울,인천,서바이벌,게임,스릴러,글로벌,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_005', '도깨비', '드라마', 'K-Drama', 2016, '공개', '불멸의 삶을 끝내기 위해 인간 신부가 필요한 도깨비와 그를 소환하는 소녀의 판타지 로맨스 드라마.', '공유, 김고은, 이동욱, 유인나, 육성재', 'https://upload.wikimedia.org/wikipedia/ko/6/63/%EB%93%9C%EB%9D%BC%EB%A7%88_%EB%8F%84%EA%B9%A8%EB%B9%84_%ED%8F%AC%EC%8A%A4%ED%84%B02.jpg', TRUE, 'Korea', 'tvN / TVING / Netflix', '강릉,주문진,덕수궁,인천,판타지,로맨스,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_006', '갯마을 차차차', '드라마', 'K-Drama', 2021, '공개', '대도시를 떠난 치과의사와 바닷가 마을의 만능 백수가 공진마을에서 만들어가는 힐링 로맨스 드라마.', '신민아, 김선호, 이상이', 'https://upload.wikimedia.org/wikipedia/en/3/3e/Hometown_Cha-Cha-Cha.jpg', TRUE, 'Korea', 'tvN / TVING / Netflix', '포항,청하,바다,공진마을,힐링,로맨스,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_007', '그 해 우리는', '드라마', 'K-Drama', 2021, '공개', '헤어진 연인이 고등학교 시절 다큐멘터리의 역주행으로 다시 카메라 앞에 서게 되는 청춘 로맨스 드라마.', '최우식, 김다미, 김성철, 노정의', 'https://upload.wikimedia.org/wikipedia/en/2/29/Our_Beloved_Summer.jpg', TRUE, 'Korea', 'SBS / Netflix', '서울,수원,화성행궁,카페,청춘,감성,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_008', '사랑의 불시착', '드라마', 'K-Drama', 2019, '공개', '패러글라이딩 사고로 북한에 불시착한 재벌 상속녀와 그녀를 숨기고 지키는 북한 장교의 극비 로맨스 드라마.', '현빈, 손예진, 서지혜, 김정현', 'https://upload.wikimedia.org/wikipedia/en/5/5e/Crash_Landing_on_You_poster.png', TRUE, 'Korea', 'tvN / TVING / Netflix', '충주,순창,비내섬,자연,로맨스,힐링,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_009', '이 사랑 통역 되나요?', '드라마', 'K-Drama', 2026, '예정', '글로벌 톱스타와 다중언어 통역사가 촬영 현장을 오가며 서로의 사랑의 언어를 찾아가는 로맨틱 코미디 드라마.', '김선호, 고윤정, 후쿠시 소타', 'https://upload.wikimedia.org/wikipedia/en/1/1d/Can_This_Love_Be_Translated%3F_Poster.png', TRUE, 'Korea', 'Netflix', '통역,글로벌,해외촬영,도쿄,로맨스,스타배우', CURRENT_TIMESTAMP),
('C_DRAMA_010', '21세기 대군부인', '드라마', 'K-Drama', 2026, '예정', '21세기 입헌군주제 대한민국에서 재벌 평민 성희주와 왕의 아들 이안대군이 신분의 벽을 넘는 로맨스 드라마.', '아이유, 변우석, 노상현, 공승연', 'https://upload.wikimedia.org/wikipedia/en/7/76/Perfect_Crown_poster.png', TRUE, 'Korea', 'MBC / Disney+', '궁궐,현대도시,입헌군주제,왕실,로맨스,가상역사', CURRENT_TIMESTAMP),
('C_DRAMA_011', '부부의 세계', '드라마', 'K-Drama', 2020, '공개', '완벽하다고 믿었던 부부의 세계가 배신과 의심으로 무너지는 과정을 그린 치정 멜로 스릴러 드라마.', '김희애, 박해준, 한소희, 김영민', 'https://upload.wikimedia.org/wikipedia/en/7/76/The_World_of_the_Married.jpg', TRUE, 'Korea', 'JTBC / TVING', '강릉,고산,부부,불륜,멜로,스릴러,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_DRAMA_012', '철인왕후', '드라마', 'K-Drama', 2020, '공개', '현대 남성의 영혼이 조선 중전 김소용의 몸에 깃들며 벌어지는 영혼가출 퓨전 사극 코미디 드라마.', '신혜선, 김정현, 배종옥, 김태우', 'https://upload.wikimedia.org/wikipedia/en/e/e7/Mr._Queen_poster.jpg', TRUE, 'Korea', 'tvN / TVING', '용인대장금파크,문경새재,궁궐,사극,코미디,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_MOVIE_001', '파묘', '영화', 'K-Movie', 2024, '공개', '수상한 묘를 이장한 풍수사와 장의사, 무속인들이 기이한 사건과 묻힌 진실을 마주하는 오컬트 미스터리 영화.', '최민식, 김고은, 유해진, 이도현', 'https://upload.wikimedia.org/wikipedia/en/1/13/Exhuma_film_poster.jpg', FALSE, 'Korea', 'Theatrical', '무속,풍수,전통,장례,오컬트,미스터리,지역테마', CURRENT_TIMESTAMP),
('C_MOVIE_002', '범죄도시4', '영화', 'K-Movie', 2024, '공개', '괴물형사 마석도가 온라인 불법 도박 조직과 특수부대 용병 출신 빌런에 맞서는 범죄 액션 영화.', '마동석, 김무열, 박지환, 이동휘', 'https://upload.wikimedia.org/wikipedia/en/a/ae/The_Roundup_Punishment_film_poster.jpg', FALSE, 'Korea', 'Theatrical', '서울,도시액션,범죄,형사,액티비티,흥행작', CURRENT_TIMESTAMP),
('C_MOVIE_003', '왕과 사는 남자', '영화', 'K-Movie', 2026, '예정', '조선 단종의 유배와 엄흥도를 둘러싼 이야기를 바탕으로 한 역사 드라마 영화.', '유해진, 박지훈, 유지태, 전미도', 'https://upload.wikimedia.org/wikipedia/ko/c/c4/%EC%99%95%EA%B3%BC_%EC%82%AC%EB%8A%94_%EB%82%A8%EC%9E%90.jpg', FALSE, 'Korea', 'Theatrical', '영월,청령포,장릉,단종,엄흥도,사극,역사여행', CURRENT_TIMESTAMP),
('C_MOVIE_004', '케이팝 데몬 헌터스', '영화', 'K-Movie', 2025, '공개', 'K팝 슈퍼스타 루미, 미라, 조이가 악마 사냥꾼이라는 비밀 정체로 팬들을 지키는 애니메이션 뮤지컬 판타지 영화.', '아든 조, 안효섭, 메이 홍, 유지영, 김윤진, 대니얼 대 킴', 'https://upload.wikimedia.org/wikipedia/en/9/93/KPDHposter.jpeg', TRUE, 'Korea', 'Netflix', 'K팝,아이돌,애니메이션,서울,판타지,음악,글로벌', CURRENT_TIMESTAMP),
('C_MOVIE_005', '헤어질 결심', '영화', 'K-Movie', 2022, '공개', '산악인의 죽음을 수사하는 형사가 사망자의 미스터리한 아내에게 의심과 관심을 동시에 느끼는 수사 멜로 영화.', '박해일, 탕웨이, 이정현, 고경표', 'https://upload.wikimedia.org/wikipedia/en/8/82/Decision_to_Leave_film_poster.jpg', TRUE, 'Korea', 'TVING / Netflix', '부산,산,바다,수사,멜로,미스터리,감성', CURRENT_TIMESTAMP),
('C_VARIETY_001', '환승연애', '예능', 'K-Variety', 2021, '공개', '다양한 이유로 이별한 커플들이 한 공간에 모여 지나간 사랑과 새로운 사랑을 선택하는 연애 리얼리티 예능.', '사이먼 도미닉, 이용진, 김예원, 유라', 'https://upload.wikimedia.org/wikipedia/en/9/98/EXchange_4_poster.webp', TRUE, 'Korea', 'TVING', '서울,제주,데이트,숙소,연애리얼리티,감성', CURRENT_TIMESTAMP),
('C_VARIETY_002', '런닝맨', '예능', 'K-Variety', 2010, '공개', '출연진과 게스트가 전국 곳곳에서 미션과 레이스를 수행하는 장수 버라이어티 예능.', '유재석, 지석진, 김종국, 하하, 송지효, 양세찬, 지예은', 'https://images.khan.co.kr/article/2024/04/15/news-p.v1.20240414.db4acbb57fb64421bb63e36131051214_P1.png', TRUE, 'Korea', 'SBS', '전국,미션,레이스,액티비티,버라이어티,촬영지데이터보유', CURRENT_TIMESTAMP),
('C_VARIETY_003', '대환장 기안장', '예능', 'K-Variety', 2025, '공개', '기안84가 울릉도에서 기상천외한 민박을 열고 진과 지예은이 직원으로 함께하는 여행 리얼리티 예능.', '기안84, 진, 지예은', 'https://images.khan.co.kr/article/r/700xX/2025/03/25/news-p.v1.20250325.23c8cc5e52564e9f8a32c3c1d4d81b18_P1.png', TRUE, 'Korea', 'Netflix', '울릉도,민박,여행,기안84,BTS진,지예은,숙박', CURRENT_TIMESTAMP),
('C_VARIETY_004', '핑계고', '예능', 'K-Variety', 2022, '공개', '유재석이 지인과 게스트를 만나 자유로운 분위기에서 이야기를 나누는 유튜브 토크 웹예능.', '유재석 외 게스트', 'https://i.ytimg.com/vi/yrdlOEbXqp0/maxresdefault.jpg', FALSE, 'Korea', 'YouTube / 뜬뜬', '서울,토크,유재석,웹예능,게스트,카페감성', CURRENT_TIMESTAMP),
('C_VARIETY_005', '솔로지옥', '예능', 'K-Variety', 2021, '공개', '매력적인 싱글 남녀가 무인도 지옥도와 데이트 장소 천국도를 오가며 커플이 되기 위해 선택하는 연애 리얼리티 예능.', '홍진경, 이다희, 규현, 한해, 덱스', 'https://assets.repress.co.kr/photos/f873d6547a30e4c4f36afe101a1609b7/thumb.jpg', FALSE, 'Korea', 'Netflix', '사승봉도,인천,천국도,무인도,연애리얼리티,데이트', CURRENT_TIMESTAMP)
ON DUPLICATE KEY UPDATE title = VALUES(title), category = VALUES(category), subcategory = VALUES(subcategory), release_year = VALUES(release_year), status = VALUES(status), description = VALUES(description), cast_names = VALUES(cast_names), thumbnail_url = VALUES(thumbnail_url), is_popular = VALUES(is_popular), country = VALUES(country), ott_platform = VALUES(ott_platform), tags = VALUES(tags);

