('P_0002', '서울랜드', '경기', '과천시', '경기 과천시 광명로 181', '테마파크', '[오징어게임2] 2화에 등장하는 놀이공원', '시설별 상이', '시설별 상이', '정보없음', 'https://upload.wikimedia.org/wikipedia/commons/4/42/2015%EB%85%84_5%EC%9B%94_5%EC%9D%BC_%EC%84%9C%EC%9A%B8%EB%9E%9C%EB%93%9C_%EC%A0%84%EA%B2%BD_DSC09925.jpg', 'mixed', FALSE, 37.4339028, 127.0187021),
('P_0003', '금성루', '서울', '중구', '서울 중구 충무로2길 25', '맛집', '[오징어게임2]', '시설별 상이', '시설별 상이', '정보없음', NULL, 'mixed', FALSE, 37.5625391, 126.9945989),
('P_0004', '팔도건어물', '서울', '도봉구', '서울 도봉구 삼양로154길 36', '촬영지', '[오징어게임] 상우 어머니가 운영하던 생선 가게', '정보없음', '정보없음', '02-999-8448', NULL, 'mixed', FALSE, 37.6555996, 127.0152309),
('P_0005', '백운시장', '서울', '도봉구', '서울 도봉구 삼양로154길 42', '시장', '[오징어게임] 1-2화에서 조상우의 어머니(박혜진)는 ''쌍문의 자존심''인 성공한 아들의 사진을 자랑스럽게 걸어둔  ''상우의 생선가게''라는 생선가게를 이 시장에서 운영하고 있다.', '매일 09시 - 18시 (상인회 사무실 기준)', '연중무휴', '02-991-0678', NULL, 'mixed', FALSE, 37.6557113, 127.0155981),
