('P_0019', '건국대학교', '서울', '광진구', '서울 광진구 능동로 120', '학교', '[도깨비] 지은탁(김고은)이 7화에서 여기서 통신전공 논술전형을 치른다. 일이 끝났을 때, 그녀는 우연히 대학 야구팀의 일원인 그녀의 짝사랑하는 태희(정해인)와 마주친다. 은탁을 데리러 이곳에 와서 건국대학교 박물관 앞에서 기다리는 김신(공유)은 그들의 재회를 마지못해 목격하게 된다. 12화 후반부에서, 우리는 그녀가 학생일 때 캠퍼스를 걷는 것을 본다. 13화에서 저승사자(이동욱)는 은탁(학생회 건물 옥상 카페일 가능성이 높다)을 만나기 위해 이곳에 와서 신정아가 가슴에 품고 있는 칼을 뽑아준다. 조금 후, 그리고 그들의 여행이 끝난 후, 신씨는 깜짝 방문을 위해 이곳에 온다.', '매일 00시 - 24시', '연중무휴', '02-450-3114', 'https://upload.wikimedia.org/wikipedia/commons/c/c2/%EC%A0%84%EA%B2%BD_%281%29%28%ED%95%84%EC%88%98%29.jpg', 'mixed', FALSE, 37.5435361, 127.0774164),
('P_0020', '그랜드 워커힐 서울', '서울', '광진구', '서울 광진구 워커힐로 177', '호텔', '[도깨비] 4회에서 지은탁(김고은)이 이 호텔에 묵는다.', '매일 입실 15시, 퇴실 11시', '연중무휴', '02-455-5000', NULL, 'mixed', TRUE, 37.5552278, 127.1108926),
