('P_0025', '이화벽화마을', '서울', '종로구', '서울 종로구 낙산성곽서1길 28', '거리', '[도깨비] 2화에서 지은탁(김고은)이 귀신들과 대화하고 김신(공유)에게 감시당하는 곳도 바로 이 곳이다.', '매일 00시 - 24시', '연중무휴', '02-2148-5306', NULL, 'outdoor', FALSE, 37.5782567, 127.0080096),
('P_0026', '경복궁', '서울', '종로구', '서울 종로구 사직로 161', '궁궐', '[도깨비] 2화 퀘벡에서 돌아온 김신(공유)과 지은탁(김고은)이 이곳에 도착해 함께 광화문을 지나간다. / [케이팝 데몬 헌터스] 진우의 과거 회상과 조선 왕궁 이미지의 실제 배경.', '수-월 09시 - 17시 (11월-2월), 수-월 09시 - 18시 (3-5월, 9-10월), 수-월 09시 - 18시 30분 (6-8월)', '화요일(공휴일인 경우 다음날 휴무)', '02-3700-3900', 'https://upload.wikimedia.org/wikipedia/commons/6/63/%EA%B4%91%ED%99%94%EB%AC%B8_%EC%9B%94%EB%8C%80.jpg', 'outdoor', FALSE, 37.5776133, 126.9768979),
('P_0027', '운현궁 양관', '서울', '종로구', '서울 종로구 삼일대로 464', '관광지', '[도깨비] 김신(공유)가 사는 곳이다. 이후 저승사자(이동욱)와 지은탁(김고은)도 입주한다. 유덕화(육성재)가 이곳에 사는 것처럼 자주 드나든다.', '하절기 화-일 09시 - 19시, 동절기 화-일 09시 - 18시', '월요일', '02-765-1846', 'https://upload.wikimedia.org/wikipedia/commons/d/df/Western_House_of_Unhyeongung.jpg', 'outdoor', FALSE, 37.5762264, 126.9870856),
('P_0028', '윤보선길', '서울', '종로구', '서울 종로구 윤보선길', '거리', '[도깨비] 1, 2회에서 지은탁(김고은)이 1화에서 이 골목에서 하교하고 2화에서 율곡로3길에 들어서는 모습이 나온다. / [그 해 우리는] 3화에서 국연수(김다미)는 술에 취한 최웅(최우식)을 업고 이 골목으로 내려온다. 5화에서 최웅과 김지웅(김성철)이 이곳에서 자전거를 탄다. 또한 16화에서 이 골목은 최웅이 국연수에게 처음으로 사랑한다고 말하는 곳으로 이어진다.', '매일 00시 - 24시', '연중무휴', '02-2148-1114', NULL, 'outdoor', FALSE, 37.5778209, 126.9837129),
('P_0029', '자작나무이야기', '서울', '종로구', '서울 종로구 율곡로1길 74-15', '카페', '[도깨비] 11화에서 써니(유인나)와 지은탁(김고은)이 이곳에 온다.  써니는 은탁에게 전생을 믿느냐고 물었고, 그녀는 그렇다고 대답한다.', '매일 12시 - 22시', '연중무휴', '02-730-7932', NULL, 'indoor', FALSE, 37.5786782, 126.9818436),
