('P_0273', '송파나루공원 석촌호수', '서울', '송파구', '서울 송파구 삼학사로 136', '공원', '[BTS] RM이 호숫가 사진을 올린 장소로 소개된 서울 도심 산책 명소. 롯데월드타워·롯데월드와 연계하기 좋다.', '00:00-24:00', '연중무휴', '02-412-0190', NULL, 'outdoor', TRUE, 37.5090627, 127.0978678),
('P_0274', '유정식당', '서울', '강남구', '서울 강남구 도산대로28길 14', '맛집', '[BTS] 멤버들이 연습생 시절 자주 방문한 식당으로 유명한 팬 성지. 내부에 BTS 사진과 포스터가 많다.', '월-금 10:00-21:30, 토-일 10:00-20:00', '연중무휴', '02-511-4592', NULL, 'indoor', FALSE, 37.5183364, 127.0280938),
('P_0275', '이호테우해변', '제주', '제주시', '제주특별자치도 제주시 이호이동', '해변', '[BTS] 진이 SNS에 사진을 올린 장소로 소개되는 제주 해변. 빨간·흰 말등대와 석양 포토 스팟으로 유명하다.', '00:00-24:00', '연중무휴', '064-740-6000', 'https://upload.wikimedia.org/wikipedia/commons/2/28/Iho_Tewoo_Beach_01.jpg', 'outdoor', TRUE, 33.4953082, 126.4546623),
('P_0276', '외돌개', '제주', '서귀포시', '제주특별자치도 서귀포시 서홍동 791', '관광지', '[BTS] 「화양연화 pt.2」 앨범 재킷 촬영지로 소개되는 제주 해안 기암 명소.', '00:00-24:00', '연중무휴', '064-760-3192', 'https://upload.wikimedia.org/wikipedia/commons/b/bc/%EC%99%B8%EB%8F%8C%EA%B0%9C.jpg', 'outdoor', TRUE, 33.2390338, 126.5448623),
('P_0277', '제주베스트힐', '제주', '제주시', '제주특별자치도 제주시 조천읍 남조로 2109-36', '관광지', '[BTS] 「Young Forever」 Day Version 사진 촬영지로 소개되는 제주 글램핑·체험 공간.', '체크인 15:00, 체크아웃 11:00', '방문 전 확인', '070-4400-3300', NULL, 'mixed', TRUE, 33.4538387, 126.6577143),
('P_0278', '스누피가든', '제주', '제주시', '제주특별자치도 제주시 구좌읍 금백조로 930', '관광지', '[BTS] 지민의 SNS 사진으로 팬들에게 알려진 제주 실내외 테마 정원.', '09:00-19:00(입장마감 18:00)', '연중무휴', '064-903-1111', NULL, 'mixed', TRUE, 33.444131, 126.7781674),
('P_0279', '감천문화마을', '부산', '사하구', '부산 사하구 감천동 1-17', '거리', '[BTS] 부산 출신 멤버 지민·정국 벽화가 있는 감천문화마을 포토 스팟. 부산 BTS 팬투어 코스로 활용하기 좋다.', '시설별 상이', '연중무휴', '051-204-1444', 'https://upload.wikimedia.org/wikipedia/commons/4/49/Gamcheon_Colored_Houses%2C_Busan%2C_Korea.jpg', 'outdoor', TRUE, 35.0974087, 129.0105608),
('P_0280', '서동미로시장 맛나분식', '부산', '금정구', '부산 금정구 서동시장길 42-4', '맛집', '[BTS] 지민이 어린 시절 즐겨 먹었다고 소개되는 계란만두 코스. 서동미로시장 내 맛나분식 방문 동선과 연결된다.', '시설별 상이', '시설별 상이', '051-522-9757', NULL, 'indoor', FALSE, 35.2164308, 129.1006545),
('P_0281', '부산시민공원', '부산', '부산진구', '부산 부산진구 시민공원로 73', '공원', '[BTS] 부산 BTS 팬투어에서 V·지민 포즈를 따라 찍는 장소로 소개되는 도심 공원.', '05:00-24:00', '연중무휴', '051-850-6000', 'https://upload.wikimedia.org/wikipedia/commons/7/73/Busan_Citizens_Park_%22mirror_pond%22.jpg', 'outdoor', TRUE, 35.1683563, 129.0574038)
ON DUPLICATE KEY UPDATE place_name = VALUES(place_name), region = VALUES(region), district = VALUES(district), address = VALUES(address), category = VALUES(category), description = VALUES(description), opening_hours = VALUES(opening_hours), closed_days = VALUES(closed_days), phone_number = VALUES(phone_number), image_url = VALUES(image_url), indoor_outdoor = VALUES(indoor_outdoor), parking_available = VALUES(parking_available), latitude = VALUES(latitude), longitude = VALUES(longitude);

INSERT IGNORE INTO content_places (content_id, place_id, relation_description, sort_order)
VALUES
('C_DRAMA_004', 'P_0001', '촬영지 · 9화 · 마지막 9화에서 로스앤젤레스로 가는 장면에서 공항으로 나온다.', 1),
('C_DRAMA_004', 'P_0002', '촬영지 · 2화 · 2화에 등장하는 놀이공원', 2),
('C_DRAMA_004', 'P_0003', '촬영지 · 정보없음 · 오징어 게임 관련 장소로 소개된 금성루 위치.', 3),
('C_DRAMA_004', 'P_0004', '촬영지 · 정보없음 · 상우 어머니가 운영하던 생선 가게', 4),
('C_DRAMA_004', 'P_0005', '촬영지 · 1-2화 · 1-2화에서 조상우의 어머니(박혜진)는 ''쌍문의 자존심''인 성공한 아들의 사진을 자랑스럽게 걸어둔 ''상우의 생선가게''라는 생선가게를 이 시장에서 운영하고 있다.', 5),
('C_DRAMA_004', 'P_0006', '촬영지 · 정보없음 · 선생님, 저랑 게임 한 번 하시겠습니까''라며 오징어게임 시작을 알린 딱치지기 장면', 6),
('C_DRAMA_004', 'P_0007', '촬영지 · 정보없음 · 투표로 오징어 게임이 중단되고 헤어지는 곳', 7),
('C_DRAMA_004', 'P_0008', '촬영지 · 8회 · 8회에서 오징어게임의 최전선(이병헌)과 그의 부하들이 해변에서 서쪽 바다가 내려다보이는 절벽 끝까지 서울경찰과 게임 잠입자 황준호(위하준)를 쫓는다.', 8),
('C_DRAMA_004', 'P_0009', '촬영지 · 2화 · 경기가 중단된 후, 조폭 장덕수(허성태)는 이 놀이동산 밖에서 지인을 만난다. 2화에서 상금을 훔치기 위해 갱단과 함께 섬으로 돌아갈 것을 제안한다.', 9),
('C_DRAMA_004', 'P_0010', '촬영지 · 2화 · 성기훈(이정재)이 자신을 실종된 형에게로 인도할 수 있다고 의심한 경찰 황준호(위하준)는 2화에서 그를 태운 밴을 따라 이 항구로 등장한다.', 10),
('C_DRAMA_005', 'P_0011', '촬영지 · 1회 · 1회에서 이곳은 지은탁(김고은)이 도깨비에서 어린 소녀였을 때 사는 곳이기도 하다.', 1),
('C_DRAMA_005', 'P_0012', '촬영지 · 정보없음 · SNS에서 유명한 도깨비 방파제 촬영지', 2),
('C_DRAMA_005', 'P_0013', '촬영지 · 정보없음 · 공유가 중천의 허무를 걷는 장면 촬영지', 3),
('C_DRAMA_005', 'P_0014', '촬영지 · 정보없음 · 김고은이 집 나와서 일하러 간 스키장', 4),
('C_DRAMA_005', 'P_0015', '촬영지 · 정보없음 · 공유가 집 나온 김고은을 따라가던 촬영지', 5),
('C_DRAMA_005', 'P_0016', '촬영지 · 9화 · 9화에서 이 사찰로 가는 길과 전나무길은 지은탁(김고은)의 아르바이트 마치고 집으로 가는 길로 등장한다.', 6),
('C_DRAMA_005', 'P_0017', '촬영지 · 정보없음 · 공유가 풍등을 날리던 그 절', 7),
('C_DRAMA_005', 'P_0018', '촬영지 · 정보없음 · 캐나다에서 공유와 김고은이 밥 먹은 레스토랑', 8),
('C_VARIETY_002', 'P_0018', '예능방문지 · 446회 · 런닝맨 446회 데이트 & 미션 장소', 1),
('C_DRAMA_005', 'P_0019', '촬영지 · 7화, 12화, 13화 · 지은탁(김고은)이 7화에서 여기서 통신전공 논술전형을 치른다. 일이 끝났을 때, 그녀는 우연히 대학 야구팀의 일원인 그녀의 짝사랑하는 태희(정해인)와 마주친다. 은탁을 데리러 이곳에 와서 건국대학교 박물관 앞에서 기다리는 김신(공유)은 그들의 재회를 마지못해 목격하게 된다. 12화 후반부에서, 우리는 그녀가 학생일 때 캠퍼스를 걷는 것을 본다. 13화에서 저승사자(이동욱)는 은탁(학생회 건물 옥상 카페일 가능성이 높다)을 만나기 위해 이곳에 와서 신정아가 가슴에 품고 있는 칼을 뽑아준다. 조금 후, 그리고 그들의 여행이 끝난 후, 신씨는 깜짝 방문을 위해 이곳에 온다.', 9),
('C_DRAMA_005', 'P_0020', '촬영지 · 4회 · 4회에서 지은탁(김고은)이 이 호텔에 묵는다.', 10),
('C_DRAMA_005', 'P_0021', '촬영지 · 1화 · 1화에서 지은탁(김고은)은 이곳에서 촛불을 불어주는 앱으로 김신(공유)을 부를 수 있다는 자신의 이론을 시도한다.', 11),
('C_DRAMA_005', 'P_0022', '촬영지 · 10화 · 10화에서 김신(공유)과 저승사자(이동욱)는 지은탁(김고은)을 위해 파(대파)를 사준 뒤 이 터널을 활주로를 걸었고, 오토바이 운전자가 그들 사이를 지나갔습니다.', 12),
('C_DRAMA_005', 'P_0023', '촬영지 · 12회 · 12회에서 혼란스러운 저승사자(이동욱)가 동료 저승사자를 이곳에서 만난다.', 13),
('C_DRAMA_005', 'P_0024', '촬영지 · 3회 · 3회에서 저승사자(이동욱 분)와 써니(유인나 분)의 첫 만남이 이 육교에서 벌어졌다.', 14),
('C_DRAMA_005', 'P_0025', '촬영지 · 2화 · 2화에서 지은탁(김고은)이 귀신들과 대화하고 김신(공유)에게 감시당하는 곳도 바로 이 곳이다.', 15),
('C_DRAMA_005', 'P_0026', '촬영지 · 2화 · 2화 퀘벡에서 돌아온 김신(공유)과 지은탁(김고은)이 이곳에 도착해 함께 광화문을 지나간다.', 16),
('C_MOVIE_004', 'P_0026', '배경장소 · 영화 · 진우의 과거 회상과 조선 왕궁 이미지의 실제 배경.', 1),
('C_DRAMA_005', 'P_0027', '촬영지 · 정보없음 · 김신(공유)가 사는 곳이다. 이후 저승사자(이동욱)와 지은탁(김고은)도 입주한다. 유덕화(육성재)가 이곳에 사는 것처럼 자주 드나든다.', 17),
('C_DRAMA_005', 'P_0028', '촬영지 · 1, 2회, 1화, 2화 · 1, 2회에서 지은탁(김고은)이 1화에서 이 골목에서 하교하고 2화에서 율곡로3길에 들어서는 모습이 나온다.', 18),
('C_DRAMA_007', 'P_0028', '촬영지 · 3화, 5화, 16화 · 3화에서 국연수(김다미)는 술에 취한 최웅(최우식)을 업고 이 골목으로 내려온다. 5화에서 최웅과 김지웅(김성철)이 이곳에서 자전거를 탄다. 또한 16화에서 이 골목은 최웅이 국연수에게 처음으로 사랑한다고 말하는 곳으로 이어진다.', 1),
('C_DRAMA_005', 'P_0029', '촬영지 · 11화 · 11화에서 써니(유인나)와 지은탁(김고은)이 이곳에 온다. 써니는 은탁에게 전생을 믿느냐고 물었고, 그녀는 그렇다고 대답한다.', 19),
('C_DRAMA_005', 'P_0030', '촬영지 · 정보없음 · 공유와 김고은이 처음 우연히 마주친 돌담길', 20),
('C_DRAMA_005', 'P_0031', '촬영지 · 12화 · 12화에서 지은탁(김고은)이 이 거리를 걷는다.', 21),
('C_DRAMA_005', 'P_0032', '촬영지 · 정보없음 · 지은탁(김고은)이 다니던 학교이다.', 22),
('C_DRAMA_007', 'P_0032', '촬영지 · 1회 · 1회에서 학교 일부가 최웅(최우식)과 국연수( 김다미)의 고등학교로 촬영되었다.', 2),
('C_DRAMA_005', 'P_0033', '촬영지 · 정보없음 · 공유와 김고은이 캐나다에서 돌아온 커다란 문', 23),
('C_DRAMA_005', 'P_0034', '촬영지 · 정보없음 · 저승사자(이동욱) 사무실은 이 곳 궁전 벽 안에 있습니다. 김신(공유)이 1편과 14편에서 이곳을 지나며 잡담을 나눈다.', 24),
('C_DRAMA_005', 'P_0035', '촬영지 · 14회 · 14회에서 김신(공유)과 지은탁(김고은)이 한미 서점에서 만난 후, 김신은 돌아왔지만 은탁은 기억을 잃었다.', 25),
('C_DRAMA_005', 'P_0036', '촬영지 · 정보없음 · 김고은 집 앞 골목 촬영지', 26),
('C_DRAMA_005', 'P_0037', '촬영지 · 정보없음 · 납치당한 김고은을 구하기 위해 공유가 걷던 거리', 27),
('C_DRAMA_005', 'P_0038', '촬영지 · 4회, 13회 · 4회에서는 취한 신이 은탁에게 자신이 처음이자 마지막 신부라는 사실을 알리며 차분한 마음으로 했을 것 같은 자신에 대해 조금 더 이야기한다. 13회에서 은탁은 그를 보고 싶다고 그를 여기로 불렀다.', 28),
('C_DRAMA_005', 'P_0039', '촬영지 · 13회 · 13회에서 지은탁(김고은)이 머무는 장소로 나온다.', 29),
('C_DRAMA_008', 'P_0039', '촬영지 · 10화 · 10화에서는 북한 스포츠팀이 이 호텔에 도착한다. 세리가 운영하는 호텔로 나온다', 1),
('C_DRAMA_005', 'P_0040', '촬영지 · 8화 · 8화에서 김신(공유)과 지은탁(김고은)이 산책하러 왔다.', 30),
('C_DRAMA_005', 'P_0041', '촬영지 · 정보없음 · 이동욱이 공유에게 사과를 한 장소', 31),
('C_DRAMA_005', 'P_0042', '촬영지 · 14회 · 14회에서 김신(공유)은 지은탁(김고은)은 한미서점에서 만난 후 이곳을 산책한다.', 32),
('C_DRAMA_005', 'P_0043', '촬영지 · 정보없음 · 김고은이 불을 꺼서 공유를 부르던 장소', 33),
('C_DRAMA_005', 'P_0044', '촬영지 · 정보없음 · 공유와 김고은이 첫키스한 그 메밀밭', 34),
('C_DRAMA_006', 'P_0045', '촬영지 · 정보없음 · 신민아와 김선호가 미술관 데이트를 즐긴 미술관', 1),
('C_DRAMA_006', 'P_0046', '촬영지 · 정보없음 · 신민아와 김선호가 골프 데이트를 즐긴 골프장', 2),
('C_DRAMA_006', 'P_0047', '촬영지 · 정보없음 · 신민아가 김선호에게 사랑 고백했던 방파제', 3),
('C_DRAMA_006', 'P_0048', '촬영지 · 정보없음 · 갯마을 차차차의 슈퍼, 철물점, 카페가 있는 5일장', 4),
('C_DRAMA_006', 'P_0049', '촬영지 · 정보없음 · 신민아와 김선호가 갔던 언덕 위에 배가 있는 공원', 5),
('C_DRAMA_006', 'P_0050', '촬영지 · 3화 · 3화에서 윤혜진(신민아)과 홍두식(김선호)이 서울을 떠나 이 다리를 건너는 장면이 나온다.', 6),
('C_DRAMA_006', 'P_0051', '촬영지 · 10회 · 10회에서 서울 여행길에 오른 윤혜진(신민아)과 절친 표미선(공민정)이 이곳에서 저녁을 먹는다. 혜진은 공진 바다에서 살다 보니 한강이 예전보다 좁아진 것 같다고 말한다. 이들이 식당을 나서자 갑자기 비가 내리기 시작하자 혜진은 홍두식(김선호)과의 달콤한 순간을 떠올리고 미선을 뒤로 한 채 자신의 차로 달려간다.', 7),
('C_DRAMA_006', 'P_0052', '촬영지 · 3화 · 3화에서 서울로 당일치기 여행을 갔을 때 윤혜진(신민아)과 홍두식(김선호)이 이 건물을 지나가다 누군가 건물 안에서 몰래 사진을 찍는다.', 8),
('C_DRAMA_007', 'P_0053', '촬영지 · 정보없음 · 솔이가 연수의 집에 머물렀던 다음날, 솔이는 자신의 길을 가기 전에 연수가 최웅(최우식)을 짝사랑하고 있다고 계속 주장한다. 고민에 빠진 연수는 잠시 발길을 멈춘 채 창에 비친 거울을 거울 삼아 생각에 잠긴 채 이 서점을 향한다.', 3),
('C_DRAMA_007', 'P_0054', '촬영지 · 정보없음 · 김다미가 아르바이트를 했던 카페', 4),
('C_DRAMA_007', 'P_0055', '촬영지 · 2회 · 2회 웅이와 연수가 연애시절 다퉜던 장소', 5),
('C_DRAMA_007', 'P_0056', '촬영지 · 정보없음 · 최우식이 김다미 할머니의 짐을 들어준 시장', 6),
('C_DRAMA_007', 'P_0057', '촬영지 · 정보없음 · 국연수(김다미)가 할머니 강자경(차미경)과 함께 사는 동네다. 하트 벽화 앞에서 말다툼을 벌인 최웅(최우식)은 국연수(김다미)에게 자기 집으로 와줄 의향이 있냐고 묻는다.', 7),
('C_DRAMA_007', 'P_0058', '촬영지 · 정보없음 · 최우식과 김다미가 첫 키스한 공원', 8),
('C_DRAMA_007', 'P_0059', '촬영지 · 15회 · 15회에서 이 도서관은 크리에이티브 에이전시 RUN의 고객이며 첫 번째 아이디어를 위해 그녀의 팀과 함께 국연수 (김다미)가 여기에 옵니다.', 9),
('C_DRAMA_007', 'P_0060', '촬영지 · 정보없음 · 최우식이 김다미에게 프러포즈한 도서관', 10),
('C_DRAMA_007', 'P_0061', '촬영지 · 8화 · 8화에서 웅과 연수가 여행간 곳을 회상한 장면', 11),
('C_DRAMA_007', 'P_0062', '촬영지 · 정보없음 · 최우식이 전시회를 연 미술관', 12),
('C_DRAMA_007', 'P_0063', '촬영지 · 정보없음 · 김다미와 이준혁이 함께 둘러본 생활용품숍', 13),
('C_DRAMA_007', 'P_0064', '촬영지 · 정보없음 · 초대받은 만찬에 무엇을 입어야 할지 고민하던 최웅(최우식)은 아이돌 NJ(노정의)에게 신발을 사러 이 쇼핑몰에 들르다가 결국 1층 화장품 코너를 빠져나온다.', 14),
('C_DRAMA_007', 'P_0065', '촬영지 · 11회 · 김지웅(김성철)은 11회에서 동료 박동일(조복래), 정채란(전혜원), 임태헌(이승우), 이민경(이선희)과 함께 이 식당에서 회식을 한다.', 15),
('C_DRAMA_007', 'P_0066', '촬영지 · 11화 · 질투심 많은 국연수(김다미)는 11화에서 이 공원 서쪽 끝에 빨간불에 멈춰 서던 중 아이돌 NJ(노정의)와 함께하는 광고를 보고 자산이 있다는 사실을 인정해야 한다.', 16),
('C_DRAMA_007', 'P_0067', '촬영지 · 정보없음 · 박진주가 운영하는 이자카야 외관으로 나온 술집', 17),
('C_DRAMA_007', 'P_0068', '촬영지 · 12회 · 12회에서 톱 아이돌 NJ(노정의)와 PD 김지웅(김성철)이 이곳에서 첫사랑의 아픔을 달래며 술잔을 기울였다.', 18),
('C_DRAMA_007', 'P_0069', '촬영지 · 1회 · 1회 회상장면에서 본 최웅(최우식)과 국연수(김다미)는 이 놀이공원에서 다섯 번째 이별을 한다.', 19),
('C_DRAMA_007', 'P_0070', '촬영지 · 13화 · 13화에서 최웅(최우식)과 국연수(김다미)가 데이트를 하며 이 다리를 건넌다.', 20),
('C_DRAMA_007', 'P_0071', '촬영지 · 1회 · 1회에서 최웅(최우식)과 국연수(김다미)가 다니던 고등학교로 이 학교의 일부가 등장한다.', 21),
('C_DRAMA_007', 'P_0072', '촬영지 · 정보없음 · 박진주가 방문했던 최우식 아빠가 운영하는 호프집', 22),
('C_DRAMA_007', 'P_0073', '촬영지 · 3화 · 3화에서 크리에이티브 에이전시 런(RUN)이 사무실을 두고 있는 ''슈퍼 크리에이티브 센터''로 등장한다.', 23),
('C_DRAMA_007', 'P_0074', '촬영지 · 정보없음 · 최웅(최우식)과 국연수(김다미)는 이 곳에서 저녁 데이트를 한다.', 24),
('C_DRAMA_007', 'P_0075', '촬영지 · 1화 · 1화에서 최웅(최우식)의 부모님이 운영하는 식당으로 나온다.', 25),
('C_DRAMA_007', 'P_0076', '촬영지 · 정보없음 · 최우식과 김다미가 캠퍼스 데이트를 즐긴 대학교', 26),
('C_DRAMA_007', 'P_0077', '촬영지 · 8회 · <그해 우리는> 8회 촬영지', 27),
('C_DRAMA_007', 'P_0078', '촬영지 · 8회 · 8회에서 이 밭의 버려진 농장 옆에서 국연수(김다미)와 함께 다큐멘터리의 일부를 촬영', 28),
('C_DRAMA_008', 'P_0079', '촬영지 · 정보없음 · 둘리커플 만남의 시작이 된 패러글라이딩 장소', 2),
('C_DRAMA_008', 'P_0080', '촬영지 · 11-12회 · 11-12회에서 이 사우나는 리정혁(현빈)의 4남 표치수(양경원), 박광범(이신영), 김주묵(유수빈), 금은동(탕준상)과 정만복(김영민)이 서울에 머무는 동안 그들의 숙소가 된다.', 3),
('C_DRAMA_008', 'P_0081', '촬영지 · 정보없음 · 둘리커플이 대화를 나눈 아찔한 높이의 하늘다리', 4),
('C_DRAMA_008', 'P_0082', '촬영지 · 정보없음 · 둘리커플이 함께 다녀간 평양의 고급 호텔', 5),
('C_DRAMA_008', 'P_0083', '촬영지 · 1화 · 이 식당의 외관은 1화에서 윤세리(손예진)가 남자친구인 차상우(정경호)와 저녁을 먹으러 가는 곳으로 등장한다. 세리-상우 데이트 파파라치가 찍힌 곳이기도 하다.', 6),
('C_DRAMA_008', 'P_0084', '촬영지 · 정보없음 · 세리 회사 홍보팀장님 닭 다리 뜯던 단골 치킨집', 7),
('C_DRAMA_008', 'P_0085', '촬영지 · 12회 · 12회에서 오매니저(윤상훈)는 같은 목표를 공유하는 조철강(오만석)과 윤세형(박형수), 고상아(윤지민) 부부를 이 식당으로 데려오려 한다.', 8),
('C_DRAMA_008', 'P_0086', '촬영지 · 정보없음 · 북한의 고위층 여성만 가는 비밀스러운 양장점', 9),
('C_DRAMA_008', 'P_0087', '촬영지 · 10회 · 10회에서 이 식당 앞에는 표치수(양경원), 박광범(이신영), 김주먹(유수빈)의 네 명의 부하 리정혁(현빈)이 있다. 그리고 금은동(당준상)과 정만복(김영민)은 영화에서 북한 첩보원으로 카메오로 등장한 북한의 비밀요원 동구(김수현)를 만난다.', 10),
('C_DRAMA_008', 'P_0088', '촬영지 · 정보없음 · 탈북 성공한 리정혁이 처음 만난 남한 바닷가', 11),
('C_DRAMA_008', 'P_0089', '촬영지 · 1화 · 이 곳은 등장인물 윤세리(손예진)의 할아버지의 저택으로 나오는 장소이다. 1화에서 윤회장(남경업)이 자녀들을 모두 이곳에 불러 가족 만찬을 하는 장면의 저택으로 등장한다.', 12),
('C_DRAMA_008', 'P_0090', '촬영지 · 정보없음 · 저세상 멋짐 리정혁 동무 수트 입고 액션하던 곳', 13),
('C_DRAMA_008', 'P_0091', '촬영지 · 정보없음 · 세리가 하늘에서 불시착해 리정혁을 만난 숲', 14),
('C_DRAMA_008', 'P_0092', '촬영지 · 4회 · 4회에서 윤세리(손예진)는 리정혁(현빈)처럼 대령의 아내의 생일파티를 떠나고 있다. 세리가 어둠 속에서 어떻게 안전하게 집에 갈 수 있을지 걱정하면서 두 번째, 세 번째로 자전거를 타고 지나간다.', 15),
('C_DRAMA_008', 'P_0093', '촬영지 · 정보없음 · 세리가 ''찬 바람이 불면~''을 열창했던 억새밭', 16),
('C_DRAMA_008', 'P_0094', '촬영지 · 정보없음 · 정혁네 부대원들과 세리가 재회 후 눈물 쏟던 곳', 17),
('C_DRAMA_008', 'P_0095', '촬영지 · 정보없음 · 서단♥구승준 커플이 키스를 나눈 무지갯빛 다리', 18),
('C_DRAMA_011', 'P_0096', '촬영지 · 정보없음 · 이무생이 김희애을 구하러 뛰어든 바다', 1),
('C_DRAMA_011', 'P_0097', '배경장소 · 8회 · 8회에서 배경의 한 장소로 나온다.', 2),
('C_DRAMA_011', 'P_0098', '촬영지 · 15회 · 15회에서 지선우(김희애)는 이 곳에서 망연자실한 이태오(박해준)를 발견하고 그와 말다툼 후에 떠난다.', 3),
('C_DRAMA_011', 'P_0099', '촬영지 · 15회 · 15회에서 벨라시타가 나온다.', 4),
('C_DRAMA_011', 'P_0100', '촬영지 · 9, 10회 · 9, 10회에서는 여병규 대표(이경영)와 김윤기 박사(이무생)를 이곳에서 만났습니다. 사위 태오(박해준)와 태오의 전 부인 선우(김희애) 사이에 어떤 감정이 남아 있을지 궁금증을 자아냅니다.', 5),
('C_DRAMA_011', 'P_0101', '촬영지 · 정보없음 · 김희애가 아들 전진서와 시간을 보내던 카페', 6),
('C_DRAMA_011', 'P_0102', '촬영지 · 1, 2화 · 1, 2화에서 이태오(박해준)의 생일파티가 열렸던 곳', 7),
('C_DRAMA_011', 'P_0103', '촬영지 · 5회 · 5회에서는 태오(박해준 분)가 아들 준영(전진서 분)을 데리고 카페로 가는 모습이 그려졌다. 그를 학교에서 데리러 온 후. 다경(한소희)이 들어오고 태오는 그녀를 멍하니 쳐다본다. 그녀는 짜증스럽게 뒤를 돌아보고 카페를 떠납니다.', 8),
('C_DRAMA_011', 'P_0104', '촬영지 · 정보없음 · 선우(긴희애), 다경(한소희)은 책값을 치르면서 서로 부딪힌 후 이 건물 밖에서 만난다.', 9),
('C_DRAMA_011', 'P_0105', '촬영지 · 1,2회 · 1,2회에서 이곳은 선우(김희애)의 환자 민현서(심은우)가 일하는 술집이다.', 10),
('C_DRAMA_011', 'P_0106', '촬영지 · 1화 · 1화에서 ''희원''이라는 식당으로 등장한 이 웨딩홀의 외관. 남편이 바람을 피우고 있다는 생각에 선우(김희애)는 이 식당에서 남편의 휴대전화로 “아름다운 밤에 또 보고 싶어 희원.”라고 보낸다.', 11),
('C_DRAMA_011', 'P_0107', '촬영지 · 정보없음 · 창공관의 외관은 지선우(김희애 분)가 부원장으로 근무하는 ''가족사랑병원''으로 등장한다.', 12),
('C_DRAMA_011', 'P_0108', '촬영지 · 정보없음 · 김희애가 남편의 생일에 떡을 주문한 곳', 13),
('C_DRAMA_010', 'P_0108', '촬영지 · 정보없음 · 문인 한옥 찻집이자 여러 콘텐츠 촬영지.', 1),
('C_DRAMA_011', 'P_0109', '촬영지 · 7회 · 7회에서 선우(김희애)는 퇴근 후 이 식당을 들르다 우연히 제혁(김영민)을 만난다. 그런 다음 그는 음식을 다 먹지 않고 떠납니다. 한편, 우연히 지나가던 윤기(이무생)는 혼자 술을 마시는 선우를 본다. 그는 그녀와 합류하고 2년 전 고산을 떠나 새 가족과 함께 돌아온 태오(박해준)에 대한 이야기를 나눕니다.', 14),
